class PhoneDropdown{constructor(element,primaryPhone,secondaryPhone){this.element=element;this.primaryPhone=primaryPhone;this.secondaryPhone=secondaryPhone;this.isOpen=false;this._render();this._bindEvents()}_render(){this.element.innerHTML=`
            <div class="phone-dropdown">
                <a href="tel:${this.primaryPhone}" class="white-link">${this.primaryPhone}</a>
                <span class="dropdown-arrow js-dropdown-arrow"></span>
                <div class="dropdown-content">
                    <a href="tel:${this.secondaryPhone}" class="white-link">${this.secondaryPhone}</a>
                </div>
            </div>
        `;this.dropdownContent=this.element.querySelector(".dropdown-content");this.dropdownArrow=this.element.querySelector(".js-dropdown-arrow")}_bindEvents(){this.dropdownArrow.addEventListener("click",()=>this.toggleDropdown())}toggleDropdown(){this.isOpen=!this.isOpen;if(this.isOpen){this.dropdownContent.style.display="block";this.dropdownArrow.classList.add("open")}else{this.dropdownContent.style.display="none";this.dropdownArrow.classList.remove("open")}}}